'use strict';

const { StrongmbError } = require('./StrongmbError');

class ApiError extends StrongmbError {
    constructor(message, apiCode, httpStatus, body = {}) {
        super(message);
        this.name     = 'ApiError';
        this.apiCode  = apiCode;
        this.httpStatus = httpStatus;
        this.body     = body;
    }

    getApiCode()   { return this.apiCode; }
    getHttpStatus() { return this.httpStatus; }
    getBody()      { return this.body; }
    getTraceId()   { return this.body?.metadata?.trace_id ?? ''; }
}

module.exports = { ApiError };
